command:
// ============================================================
// LUNAS WIRKUNG: VERBORGENER WURF (RONDRA)
//
// - Ahne aus Profession (Standard: Rondra)
// - Target-Auswahl mit GM-Anfrage und Button auf der Chatkarte
// - Dauer: QS × 10 Minuten
// - GM-Modus: Wendet die Effekte nach Klick auf den Button an
// - Wirkungsende zentral über Block 7
// - Live-Wächter für Sinnesschärfe-Proben im Chat
// ============================================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Verborgener Wurf")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN & LIVE-WÄCHTER ++++++++++++++++++++++++
    const gabenName = "Verborgener Wurf", ahne = "Rondra", finalEffektName = `${gabenName} (${ahne})`;
    const flagKey = "pendingVerborgenerWurfRondra", endeKey = "verborgenerWurf";
    const endeText = "Die verschleiernden Schatten verziehen sich. Der Verborgene Wurf ist nicht mehr aktiv und die Ziele werden wieder sichtbar.";

    DSK_FW.EffektEnde.Register(endeKey, finalEffektName, endeText);

    // Live-Wächter: Reagiert auf Sinnesschärfe-Proben im Chat
    if (globalThis._dskVerborgenerWurfHookId) {
        Hooks.off("createChatMessage", globalThis._dskVerborgenerWurfHookId);
    }

    globalThis._dskVerborgenerWurfHookId = Hooks.on("createChatMessage", async message => {
        const aktiverGM = game.users.find(u => u.isGM && u.active);
        const darfSenden = aktiverGM ? (game.user.isGM && game.user.id === aktiverGM.id) : game.user.isGM;
        if (!darfSenden || !message) return;
        if (message.speaker?.alias === "System" || message.flags?.dsk?.isWatcherMsg) return;

        const rawContent = [String(message.flavor || ""), String(message.content || "")].join(" ");
        const cleanText = rawContent.replace(/<[^>]*>?/gm, " ").replace(/\s+/g, " ").trim().toLowerCase();

        if (!cleanText.includes("sinnessch")) return;

        let hoechsteQS = 0;
        const verborgeneNamen = [];

        for (const token of canvas.tokens?.placeables || []) {
            const actor = token?.actor;
            if (!actor) continue;

            const effekt = (actor.effects || []).find(e =>
                !e.disabled && (e.name || e.label || "") === finalEffektName &&
                e.getFlag("dsk", "isVerborgenerWurf") === true
            );
            if (!effekt) continue;

            const qsVal = Math.max(1, Number(effekt.getFlag("dsk", "qs")) || 1);
            if (qsVal > hoechsteQS) hoechsteQS = qsVal;
            verborgeneNamen.push(token.name || actor.name);
        }

        if (!verborgeneNamen.length) return;

        const erschwernis = hoechsteQS * 2;
        const suchender = message.speaker?.alias || "Ein Suchender";

        const mathHtml = `
            <p style="margin-bottom:8px;">Wenn du versuchst, jemanden wahrzunehmen, greift der Effekt <b>Verborgener Wurf</b>.</p>
            <p style="margin-bottom:4px;font-weight:bold;color:#76301b;">Vorgehen:</p>
            <ul class="dsklist" style="margin-top:0;margin-bottom:0;">
                <li>Ziehe <b>${erschwernis}</b> von deinem Probenwert ab.</li>
                <li>Vergleiche den Wurf mit dem neuen Wert.</li>
                <li><b style="color:#18940F;">Erfolg:</b> Habe bitte einen Moment Geduld, die Spielleitung beschreibt dir gleich, was du entdeckst.</li>
                <li><b style="color:#B30000;">Misserfolg:</b> Du nimmst nichts wahr.</li>
            </ul>
        `;

        const whisperHtml = `
            <div style="font-family:'Signika',sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;color:#000;font-size:0.95em;">
                    <p style="margin-bottom:8px;"><b>${suchender}</b> hat eine Sinnesschärfe-Probe abgelegt.</p>
                    <hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">
                    ${mathHtml}
                </div>
            </div>
        `;

        const whisperIds = new Set(DSK_FW.Empfaenger.GM());
        const authorId = message.author?.id || message.user?.id;
        if (authorId) whisperIds.add(authorId);

        await ChatMessage.create({
            whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
            content: whisperHtml,
            speaker: { alias: "System" },
            flags: { dsk: { isWatcherMsg: true } }
        });
    });

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch {
            return null;
        }
    };

    const istGueltig = actor => {
        if (!actor) return false;
        if (actor.type === "character" || actor.type === "npc") return true;
        if (actor.type === "creature") {
            const species = String(actor.system?.species?.value || actor.system?.details?.species || "").toLowerCase();
            return ["erwacht", "erwachter", "erwachte", "tier", "tiere", "katze", "katzen", "hund", "hunde", "pferd", "pferde", "vogel", "vögel"]
                .some(w => species.includes(w));
        }
        return false;
    };

    const findeVerborgeneEffekte = actorDoc => (actorDoc?.effects || []).filter(e =>
        (e.name || e.label || "") === finalEffektName && e.getFlag("dsk", "isVerborgenerWurf") === true
    );

    const beschreibungFuer = (casterName, qs, erschwernis) =>
        `<b>${casterName}</b> webt einen magischen Schatten über sich und seine Gefährten.` +
        `<br><br>Folgende Ziele wurden geschützt und erhielten den Status <b>Unsichtbar</b>.` +
        `<br>• <b>Erschwernis auf Sinnesschärfe:</b> −${erschwernis} (${qs} QS × 2)` +
        `<br><br><b>Zielkategorie:</b> Ausgewählte Targets`;

    // +++ 4 - EFFEKTE ANWENDEN (GM-Logik) +++++++++++++++++++++++
    const wendeEffekteAn = async ({ casterActor, zieleListe, qs }) => {
        if (!casterActor || !zieleListe?.length) return { ok: false, erfolge: [], misserfolge: [] };

        const dauerMinuten = qs * 10;
        const erschwernis = qs * 2;
        const originalUnsichtbarText = `Ein Unsichtbarer ist mit dem Sehsinn nicht mehr wahrnehmbar. Er ist natürlich trotzdem weiterhin hör-, riech- und ertastbar. Im Kampf kann ein Unsichtbarer nur angegriffen werden, wenn der Angreifer sich dessen Existenz und grober Position bewusst ist. Hierzu sind vergleichende Proben auf Sinnesschärfe und Verbergen nötig. Ist der Angreifer erfolgreich, darf er Angriffe gegen den Unsichtbaren ausführen. Sämtliche Angriffswerte im Nahkampf werden hierbei um −8 erschwert, Fernkampfangriffe sind reine Glückstreffer.<br><br><b>Sonderregel Verborgener Wurf:</b> Wenn sich dieses Ziel versteckt, sind Sinnesschärfe-Proben anderer, um es zu entdecken, um ${erschwernis} erschwert!`;

        const erfolge = [];
        const misserfolge = [];

        for (const ziel of zieleListe) {
            const targetActor = await ladeActor(ziel.actorUuid);
            const targetName = ziel.name;

            if (!targetActor || !istGueltig(targetActor)) {
                misserfolge.push({ name: targetName });
                continue;
            }

            const alteEffekte = findeVerborgeneEffekte(targetActor);
            if (alteEffekte.length) {
                await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(e => e.id));
            }

            await DSK_FW.Effekt.Anwenden({
                name: finalEffektName,
                ahne,
                beschreibung: originalUnsichtbarText + `<br><br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten (${qs} QS × 10 Min.)`,
                gabeZiel: "",
                qs,
                ziel: targetActor,
                statuses: ["invisible"],
                duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime },
                showIcon: 1,
                flags: {
                    core: { statusId: "invisible" },
                    dsk: {
                        isVerborgenerWurf: true,
                        casterUuid: casterActor.uuid,
                        ahne,
                        qs,
                        erschwernis,
                        wirkungsende: {
                            sfName: endeKey,
                            basisEffektName: finalEffektName,
                            beschreibungFuerEnde: endeText
                        }
                    }
                }
            });

            erfolge.push({ name: targetName, rolle: "Verstecktes Ziel" });
            await new Promise(resolve => setTimeout(resolve, 150));
        }

        return { ok: erfolge.length > 0, erfolge, misserfolge };
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++
    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!game.user.isGM || !casterActor || !daten) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const zieleListe = daten.ziele || [];

        let res = { ok: false, erfolge: [], misserfolge: foundry.utils.deepClone(daten.misserfolge || []) };
        try {
            res = await wendeEffekteAn({ casterActor, zieleListe, qs });
        } catch (error) {
            console.error("Verborgener Wurf: Effektanlage fehlgeschlagen.", { casterActor, daten, error });
        }

        const erschwernis = qs * 2;
        const dauerText = `${qs * 10} Minuten (${qs} QS × 10 Min.)`;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: finalEffektName,
            ahne,
            beschreibung: daten.beschreibung || beschreibungFuer(casterName, qs, erschwernis),
            wirkender: casterName,
            ziele: res.erfolge,
            misserfolge: [...res.misserfolge, ...(daten.misserfolge || [])],
            dauerText,
            erfolgreich: res.ok
        });

        if (res.ok) {
            ui.notifications.info(`Luna sagt 🌙: Verborgener Wurf erfolgreich auf ${res.erfolge.length} Ziel(e) angewendet.`);
        } else {
            ui.notifications.error("Luna sagt 🌙: Verborgener Wurf konnte auf keines der Ziele angewendet werden!");
        }

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Verborgener Wurf Probe", "Verborgener Wurf"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: finalEffektName,
            ahne,
            beschreibung: "Die verschleiernden Schatten konnten nicht gewoben werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 9 - TARGETS PRÜFEN +++++++++++++++++++++++++++++++++++
    const targets = Array.from(game.user.targets || []);
    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");
    }

    const maxZiele = qs * 2;
    const gueltigeZiele = [];
    const misserfolge = [];

    for (const tToken of targets) {
        const tActor = tToken?.actor;
        const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

        if (!tActor || !istGueltig(tActor)) {
            misserfolge.push({ name: tName });
            continue;
        }

        if (gueltigeZiele.length >= maxZiele) {
            misserfolge.push({ name: `${tName} (Limit erreicht)` });
            continue;
        }

        gueltigeZiele.push({
            actorUuid: tActor.uuid,
            tokenId: tToken.id,
            tokenUuid: tToken.document?.uuid || tToken.uuid || null,
            name: tName
        });
    }

    const erschwernis = qs * 2;
    const dauerText = `${qs * 10} Minuten (${qs} QS × 10 Min.)`;
    const beschreibung = beschreibungFuer(casterName, qs, erschwernis);

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: finalEffektName,
            ahne,
            beschreibung,
            wirkender: casterName,
            ziele: [],
            misserfolge,
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 10 - KARTE + GM-BUTTON ++++++++++++++++++++++++++++++++++
    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: finalEffektName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: gueltigeZiele.map(z => ({ name: z.name, rolle: "Verstecktes Ziel" })),
        misserfolge,
        dauerText,
        gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
    }

    const anfrageDaten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        ziele: gueltigeZiele,
        misserfolge,
        qs,
        beschreibung,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid,
        erstellt: Date.now()
    };

    // +++ 11 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++
    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);

    ui.notifications.info("Luna sagt 🌙: Verborgener Wurf wurde bei der Spielleitung zur Anwendung beantragt.");
}).call(this);
